# coding: utf-8
"""Build the local glossary from versioned terminology and code examples."""
import json, html
from pathlib import Path
root = Path(__file__).resolve().parents[1]
terms = json.loads((root / 'src/data/terminology.json').read_text())
# Produce the complete browser-readable index from the same source.
items=''.join(f'<tr id="{x["id"]}"><th>{html.escape(x["label"])}<small>{html.escape(x["english"])}</small></th><td><strong>{html.escape(x["zh"])}</strong><p>{html.escape(x["definition"])}</p></td></tr>' for x in terms)
examples = ''.join('<h3>'+html.escape(x['value']+' · '+x['english'])+'</h3><pre><code>'+html.escape(x['code'])+'</code></pre>' for x in json.loads((root/'src/data/link-examples.json').read_text()))
page='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>SEO / GEO · English terminology</title><style>:root{color:#10162f;background:#fff1e7;font-family:system-ui,sans-serif}body{max-width:1080px;margin:48px auto;padding:0 24px;line-height:1.65}a{color:#a82929}h1{font-size:38px}h2{margin-top:42px}table{width:100%;border-collapse:separate;border-spacing:0;background:white;border:2px solid #10162f;border-radius:24px;overflow:hidden}th,td{text-align:left;padding:18px 22px;border-bottom:1px solid #ddd;vertical-align:top}th{width:35%}small{display:block;font-size:14px;font-weight:400}p{margin:8px 0}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#10162f;color:white;border-radius:18px;padding:22px}code{font-size:16px}a:focus-visible{outline:3px solid #38b6ff;outline-offset:3px}@media(max-width:600px){th,td{display:block;width:auto;padding:14px}th{background:#ffde59}h1{font-size:28px}}</style><header><a href="../?page=19">← 返回课件第19页</a><h1>SEO / GEO · English terminology</h1><p>保留英文术语、全称与简短中文解释。用浏览器查找功能搜索术语。</p></header><h2>HTML link examples</h2><p>以下是语法教学例子，example.com为示例域名，不代表真实合作或用户内容。href是目标地址，anchor text是可点击文字，rel说明链接关系。普通编辑性引用无需为了SEO添加特殊rel属性。</p>'''+examples+'''<p>sponsored用于付费展示；ugc用于用户提交链接；nofollow用于其他不予认可的链接关系。Google将这些属性作为提示，不是绝对禁止抓取或索引。noindex是另一种页面索引指令。商业披露不能只用HTML属性代替。</p><h2>Terminology index</h2><table>'''+items+'''</table><h2>References</h2><p><a href="https://developers.google.com/search/docs/crawling-indexing/qualify-outbound-links">Google · Qualify outbound links</a> · <a href="https://developers.google.com/search/docs/fundamentals/seo-starter-guide">Google · SEO Starter Guide</a> · <a href="https://web.dev/articles/vitals">web.dev · Web Vitals</a> · <a href="https://developers.google.com/search/docs/fundamentals/ai-optimization-guide">Google · Generative AI optimization guide</a></p></html>'''
(root/'public/materials/seo-geo-glossary.html').write_text(page)
print('Generated glossary with',len(terms),'terms')
